async function handle(req) {
  const backend = route(req);          // pick origin first
  await forwardWarmup(backend);

  try {
    if (!rateLimit(req)) return resp(429);
    if (!await waf(req)) return resp(403);
  } catch (err) {
    // gate errored — don't block the user
    return forward(req, backend);
  }

  if (!auth(req)) return resp(401);
  return forward(req, backend);
}
